## Comprehensive i18n System Analysis

I've done a thorough read of the i18n system across the monorepo. Here's the complete breakdown:

---

### 1. **`packages/i18n/src/index.ts`** — Full Contents

[index.ts](packages/i18n/src/index.ts) (252 lines)

```typescript
/**
 * `@pantoken/i18n` — Canvas-parity locale bundles for `@pantoken/web-components`.
 *
 * Ships pre-built {@link LocaleBundle} objects for all 45 Canvas-supported locales (including 3
 * RTL: Arabic, Hebrew, Persian/Farsi). Pass any bundle — or a raw BCP47 tag — to
 * {@link registerLocalized} instead of the bare `register()` from `@pantoken/web-components`:
 *
 * @example
 * ```ts
 * import { registerLocalized, hu } from "@pantoken/i18n";
 * import "@pantoken/css";
 *
 * registerLocalized(hu); // Hungarian UI strings + correct first-day-of-week
 * registerLocalized("ar"); // Arabic auto-derived; dir="rtl" inferred from CANVAS_LOCALES
 * ```
 *
 * Consumers can define custom bundles with {@link defineBundle} for locales not in this package.
 *
 * @module
 */

import { makeStrings, register, type ElementRegistry } from "@pantoken/web-components";
import { CANVAS_LOCALES } from "./lib/canvas-locales.ts";
import type { LocaleBundle } from "./locale-bundle.ts";

export type { WebComponentStrings } from "@pantoken/web-components";
export { ENGLISH_STRINGS, makeStrings } from "@pantoken/web-components";

export { CANVAS_LOCALES } from "./lib/canvas-locales.ts";
export type { LocaleMeta } from "./lib/canvas-locales.ts";
export { defineBundle } from "./locale-bundle.ts";
export type { LocaleBundle } from "./locale-bundle.ts";

// ── Locale helpers ────────────────────────────────────────────────────────────

/**
 * Return the text direction for a locale — using the {@link CANVAS_LOCALES} registry for known
 * locales, falling back to `"ltr"` for unknown tags.
 *
 * @example
 * ```ts
 * getDir("ar"); // → "rtl"
 * getDir("hu"); // → "ltr"
 * ```
 */
export function getDir(localeOrBundle: string | LocaleBundle): "ltr" | "rtl" {
  if (typeof localeOrBundle !== "string") return localeOrBundle.dir;
  return CANVAS_LOCALES[localeOrBundle]?.dir ?? "ltr";
}

// ── registerLocalized ─────────────────────────────────────────────────────────

/**
 * Register `@pantoken/web-components` custom elements with locale-specific strings and direction.
 *
 * Accepts a fully resolved {@link LocaleBundle} *or* a raw BCP47 tag string. When a string is
 * passed, {@link makeStrings} derives weekday names via `Intl.DateTimeFormat` and all other strings
 * fall back to English; pass a bundle for full translations.
 *
 * @param bundle - A {@link LocaleBundle} object, or a BCP47 tag (`"hu"`, `"ar"`, …).
 * @param target - The registry to define into (defaults to `globalThis.customElements`).
 * @param options - Passed through to `register()` (e.g. `prefix`, `only`).
 *
 * @example
 * ```ts
 * import { registerLocalized, hu } from "@pantoken/i18n";
 *
 * registerLocalized(hu);
 * registerLocalized("ar"); // direction inferred from CANVAS_LOCALES
 * registerLocalized("x-custom", customElements, { prefix: "x" });
 * ```
 */
export function registerLocalized(
  bundle: LocaleBundle | string,
  target?: ElementRegistry,
  options: { prefix?: string | null; only?: readonly string[] } = {},
): void {
  if (typeof bundle === "string") {
    const meta = CANVAS_LOCALES[bundle];
    register(target, {
      ...options,
      locale: bundle,
      dir: meta?.dir ?? "ltr",
      strings: makeStrings(bundle),
    });
  } else {
    register(target, {
      ...options,
      locale: bundle.locale,
      dir: bundle.dir,
      strings: bundle.strings,
    });
  }
}

// ── Locale set ───────────────────────────────────────────────────────────────

/**
 * A typed subset of {@link LocaleBundle}s. Created by {@link createLocaleSet} to constrain an
 * app's supported locales at compile time — registering or retrieving a locale not in the set is a
 * TypeScript error.
 */
export interface LocaleSet<K extends string> {
  /** The locale tags included in this set. */
  readonly locales: readonly K[];
  /** Type guard — true when `locale` is in this set. */
  has(locale: string): locale is K;
  /** Return the bundle for `locale`. Throws at runtime when called with an unknown locale. */
  get(locale: K): LocaleBundle;
  /** Register `@pantoken/web-components` elements with the given locale from this set. */
  register(
    locale: K,
    target?: ElementRegistry,
    options?: { prefix?: string | null; only?: readonly string[] },
  ): void;
}

/**
 * Define the locale subset your app supports. Pass the imported bundle objects as an object
 * whose keys are the locale tags (JavaScript shorthand makes this natural). TypeScript narrows
 * the accepted locale tags to only the keys you provide.
 *
 * Not calling `createLocaleSet` at all gives the full 44-locale barrel — use this factory only
 * when you need compile-time validation or explicit tree-shaking signals.
 *
 * @example
 * ```ts
 * import { createLocaleSet, en, hu, de } from "@pantoken/i18n";
 *
 * const locales = createLocaleSet({ en, hu, de });
 *
 * locales.register("hu");          // ✓ type-safe
 * locales.register("fr");          // TypeScript error — not in this set
 * locales.has("hu");               // → true (type guard)
 * locales.get("hu");               // → LocaleBundle
 * ```
 */
export function createLocaleSet<K extends string>(bundles: Record<K, LocaleBundle>): LocaleSet<K> {
  const map = new Map<string, LocaleBundle>(Object.entries(bundles));
  const locales = (Object.keys(bundles) as K[]).sort() as readonly K[];
  return {
    locales,
    has(locale): locale is K {
      return map.has(locale);
    },
    get(locale) {
      const b = map.get(locale);
      if (!b) throw new Error(`Locale "${locale}" is not in this locale set.`);
      return b;
    },
    register(locale, target?, options?) {
      registerLocalized(this.get(locale), target, options ?? {});
    },
  };
}

// ── Built-in locale bundles ───────────────────────────────────────────────────
// Each locale is defined in its own file so consumers can import selectively.
// The barrel re-exports all 45 for convenience.

export { ar } from "./locales/ar.ts";
export { ca } from "./locales/ca.ts";
export { cy } from "./locales/cy.ts";
export { da } from "./locales/da.ts";
export { de } from "./locales/de.ts";
export { el } from "./locales/el.ts";
export { en } from "./locales/en.ts";
export { enAU } from "./locales/en-AU.ts";
export { enCA } from "./locales/en-CA.ts";
export { enGB } from "./locales/en-GB.ts";
export { es } from "./locales/es.ts";
export { fa } from "./locales/fa.ts";
export { fi } from "./locales/fi.ts";
export { fr } from "./locales/fr.ts";
export { frCA } from "./locales/fr-CA.ts";
export { ga } from "./locales/ga.ts";
export { he } from "./locales/he.ts";
export { hi } from "./locales/hi.ts";
export { ht } from "./locales/ht.ts";
export { hu } from "./locales/hu.ts";
export { hy } from "./locales/hy.ts";
export { id } from "./locales/id.ts";
export { is } from "./locales/is.ts";
export { it } from "./locales/it.ts";
export { ja } from "./locales/ja.ts";
export { ko } from "./locales/ko.ts";
export { mi } from "./locales/mi.ts";
export { ms } from "./locales/ms.ts";
export { nb } from "./locales/nb.ts";
export { nl } from "./locales/nl.ts";
export { nn } from "./locales/nn.ts";
export { pl } from "./locales/pl.ts";
export { pt } from "./locales/pt.ts";
export { ptBR } from "./locales/pt-BR.ts";
export { ru } from "./locales/ru.ts";
export { se } from "./locales/se.ts";
export { sl } from "./locales/sl.ts";
export { sv } from "./locales/sv.ts";
export { th } from "./locales/th.ts";
export { tr } from "./locales/tr.ts";
export { uk } from "./locales/uk.ts";
export { vi } from "./locales/vi.ts";
export { zhHans } from "./locales/zh-Hans.ts";
export { zhHant } from "./locales/zh-Hant.ts";
```

---

### 2. **`packages/i18n/src/locale-bundle.ts`** — Full Contents

[locale-bundle.ts](packages/i18n/src/locale-bundle.ts)

```typescript
/**
 * Leaf module imported by generated locale files. Keeping `LocaleBundle`, `defineBundle`, and
 * `makeStrings` here (rather than in `index.ts`) breaks the circular dependency that arises when
 * `index.ts` re-exports the locale barrel and the locale files import back from `index.ts`.
 *
 * @module
 */
import { makeStrings } from "@pantoken/web-components";
import type { WebComponentStrings } from "@pantoken/web-components";

export type { WebComponentStrings };
export { makeStrings };

/** A fully resolved locale bundle: BCP47 tag, direction, display label, and translated strings. */
export interface LocaleBundle {
  /** BCP47 locale tag (e.g. `"hu"`, `"ar"`, `"zh-Hans"`). */
  locale: string;
  /** Text direction. */
  dir: "ltr" | "rtl";
  /** Human-readable display label. */
  label: string;
  /** Translated UI strings for the web-component element set. */
  strings: WebComponentStrings;
}

/**
 * Create and validate a {@link LocaleBundle}. Throws when required fields are missing or `locale`
 * is not a non-empty string.
 *
 * @example
 * ```ts
 * export const myLocale = defineBundle({
 *   locale: "x-acme",
 *   dir: "ltr",
 *   label: "Acme Corp Internal",
 *   strings: makeStrings("en", { back: "Return" }),
 * });
 * ```
 */
export function defineBundle(config: LocaleBundle): LocaleBundle {
  if (!config.locale || typeof config.locale !== "string")
    throw new Error("LocaleBundle requires a non-empty locale string.");
  if (config.dir !== "ltr" && config.dir !== "rtl")
    throw new Error(`LocaleBundle "${config.locale}": dir must be "ltr" or "rtl".`);
  return Object.assign({}, config);
}
```

---

### 3. **Example Locale Files**

#### [en.ts](packages/i18n/src/locales/en.ts)
```typescript
// Generated by scripts/build-bundles.ts — do not edit by hand.
import type { LocaleBundle } from "../locale-bundle.ts";
import { defineBundle, makeStrings } from "../locale-bundle.ts";

/** English (United States) locale bundle. */
export const en: LocaleBundle = defineBundle({
  locale: "en",
  dir: "ltr",
  label: "English (United States)",
  strings: makeStrings("en"),
});
```

#### [hu.ts](packages/i18n/src/locales/hu.ts)
```typescript
// Generated by scripts/build-bundles.ts — do not edit by hand.
import type { LocaleBundle } from "../locale-bundle.ts";
import { defineBundle, makeStrings } from "../locale-bundle.ts";

/** Hungarian (Magyar) locale bundle. */
export const hu: LocaleBundle = defineBundle({
  locale: "hu",
  dir: "ltr",
  label: "Hungarian (Magyar)",
  strings: makeStrings("hu", {
    prevMonth: "Előző hónap",
    nextMonth: "Következő hónap",
    dateLabel: "Dátum",
    datePlaceholder: "éééé-hh-nn",
    openCalendar: "Naptár megnyitása",
    timeLabel: "Idő",
    back: "Vissza",
  }),
});
```

**Note:** When `en.ts` is generated, it has NO overrides (only `makeStrings("en")`) because English is the source of truth. Non-English locales only include keys that differ from English.

---

### 4. **Generation Script: `packages/i18n/scripts/build-bundles.ts`**

[build-bundles.ts](packages/i18n/scripts/build-bundles.ts) (Full)

```typescript
/**
 * Generate `src/locales/{locale}.ts` files from the committed `i18n-cache/*.json` translation
 * memory. Run via `pnpm generate` or `vp run @pantoken/i18n#generate`.
 *
 * Strings absent from a locale's cache fall back to the English source value. Weekday names are
 * always derived at runtime via `Intl.DateTimeFormat` — they are not committed to the cache.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ENGLISH_STRINGS } from "@pantoken/web-components";
import { CANVAS_LOCALES } from "../src/lib/canvas-locales.ts";
import { keyFor } from "./lib/keys.ts";
import { ENGLISH_SOURCES } from "./lib/keys.ts";

// This bundle only carries `WebComponentStrings` — `keys.ts`'s auto-discovered set spans every
// package's `src/i18n.json` (for the shared drift/translate tooling), so scope down to just the
// keys `@pantoken/web-components` actually declares (`weekdays` is derived at runtime, not a key).
const WEB_COMPONENT_KEYS = Object.keys(ENGLISH_STRINGS).filter((k) => k !== "weekdays");

const root = new URL("..", import.meta.url).pathname;
const cacheDir = join(root, "i18n-cache");
const localesDir = join(root, "src", "locales");
mkdirSync(localesDir, { recursive: true });

interface CacheFile {
  version: number;
  entries: Record<string, string>;
}

function loadCache(locale: string): Record<string, string> {
  const path = join(cacheDir, `${locale}.json`);
  if (!existsSync(path)) return {};
  return (JSON.parse(readFileSync(path, "utf8")) as CacheFile).entries ?? {};
}

/** Derive the JS identifier used in the export (handles subtag locales like en-AU → enAU). */
export function toIdentifier(locale: string): string {
  return locale.replace(/-([a-zA-Z])/g, (_, c: string) => c.toUpperCase());
}

/** Produce a TS locale file for `locale`. */
export function buildLocaleFile(locale: string): string {
  const meta = CANVAS_LOCALES[locale]!;
  const entries = loadCache(locale);
  const id = toIdentifier(locale);

  // Collect only strings that differ from the English source (true translations).
  const overrides: Record<string, string> = {};
  for (const key of WEB_COMPONENT_KEYS) {
    const cacheKey = keyFor(key, ENGLISH_SOURCES[key]);
    const translated = entries[cacheKey];
    if (translated !== undefined && translated !== ENGLISH_SOURCES[key]) {
      overrides[key] = translated;
    }
  }

  const hasOverrides = Object.keys(overrides).length > 0;
  const stringsArg = hasOverrides
    ? `, {\n${Object.entries(overrides)
        .map(([k, v]) => `    ${k}: ${JSON.stringify(v)},`)
        .join("\n")}\n  }`
    : "";

  return `// Generated by scripts/build-bundles.ts — do not edit by hand.
import type { LocaleBundle } from "../locale-bundle.ts";
import { defineBundle, makeStrings } from "../locale-bundle.ts";

/** ${meta.label} locale bundle. */
export const ${id}: LocaleBundle = defineBundle({
  locale: ${JSON.stringify(locale)},
  dir: ${JSON.stringify(meta.dir)},
  label: ${JSON.stringify(meta.label)},
  strings: makeStrings(${JSON.stringify(locale)}${stringsArg}),
});
`;
}

const locales = Object.keys(CANVAS_LOCALES);
for (const locale of locales) {
  const content = buildLocaleFile(locale);
  const id = toIdentifier(locale);
  writeFileSync(join(localesDir, `${locale}.ts`), content);
  console.log(`  ${locale} → src/locales/${locale}.ts (${id})`);
}

console.log(`\n✓ i18n build-bundles: wrote ${locales.length} locale files`);
```

---

### 5. **`packages/i18n/package.json` Scripts Section**

```json
{
  "scripts": {
    "generate": "node scripts/build-bundles.ts",
    "translate": "I18N_TRANSLATION_ADAPTER=ai node scripts/translate-bundles.ts",
    "translate:agy": "I18N_TRANSLATION_ADAPTER=ai I18N_TRANSLATION_COMMAND=\"$(git rev-parse --show-toplevel)/tools/translation-adapters/agy-wrapper.sh\" node scripts/translate-bundles.ts",
    "check:drift": "node scripts/check-bundle-drift.ts",
    "dev": "vp pack --watch",
    "test": "vp test",
    "check": "vp check"
  }
}
