import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, expect, test } from "vite-plus/test";

// ── build-bundles: toIdentifier + buildLocaleFile ─────────────────────────────
// buildLocaleFile reads from the real `renderers/web-components/i18n-cache/*.json` (migrated,
// committed translation memory) — same as it always has, just without the old wc-hash keying.

const { toIdentifier, buildLocaleFile } = await import("../scripts/build-bundles.ts");

test("toIdentifier converts subtag locales to camelCase identifiers", () => {
  expect(toIdentifier("hu")).toBe("hu");
  expect(toIdentifier("en-AU")).toBe("enAU");
  expect(toIdentifier("pt-BR")).toBe("ptBR");
  expect(toIdentifier("zh-Hans")).toBe("zhHans");
});

test("buildLocaleFile produces valid TS for a translated locale (hu)", () => {
  const ts = buildLocaleFile("hu");
  expect(ts).toContain("export const hu: LocaleBundle");
  expect(ts).toContain('locale: "hu"');
  expect(ts).toContain('dir: "ltr"');
  // Hungarian translations should be non-empty overrides
  expect(ts).toContain("Vissza");
});

test("buildLocaleFile produces bare makeStrings() for English variants (en-AU)", () => {
  const ts = buildLocaleFile("en-AU");
  expect(ts).toContain("export const enAU: LocaleBundle");
  // en-AU has same values as English so no overrides argument
  expect(ts).toContain('makeStrings("en-AU")');
  expect(ts).not.toContain("prevMonth");
});

// ── check-bundle-drift: findMissingTranslations ───────────────────────────────

const { findMissingTranslations } = await import("../scripts/check-bundle-drift.ts");

let memDir: string;

beforeEach(() => {
  memDir = join(tmpdir(), `ptk-i18n-drift-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  mkdirSync(memDir, { recursive: true });
});

afterEach(() => {
  rmSync(memDir, { recursive: true, force: true });
});

test("findMissingTranslations returns empty when all keys are cached", () => {
  writeFileSync(join(memDir, "hu.json"), JSON.stringify({ back: "Vissza" }));
  const result = findMissingTranslations(memDir, ["hu"], ["back"]);
  expect(result).toHaveLength(0);
});

test("findMissingTranslations reports missing keys", () => {
  writeFileSync(join(memDir, "hu.json"), JSON.stringify({}));
  const result = findMissingTranslations(memDir, ["hu"], ["back", "timeLabel"]);
  expect(result).toEqual([
    { locale: "hu", key: "back" },
    { locale: "hu", key: "timeLabel" },
  ]);
});

test("findMissingTranslations reports every key for a missing cache file", () => {
  const result = findMissingTranslations(memDir, ["xx"], ["back"]);
  expect(result).toHaveLength(1);
  expect(result[0]).toEqual({ locale: "xx", key: "back" });
});

